import React from "react";

function Button({ text, func }) {
  return (
    <button
      onClick={func}
      className=" border-2 w-full relative flex justify-around it  text-white border-yellow-400 p-2 text-lg hover:bg-yellow-400  hover:text-black hover:scale-110 hover:border-0 transition-all"
    >
      <svg class="animate-spin h-5 w-5 mr-3 bg-white rounded-[40%]" viewBox="0 0 24 24"></svg>
      {text}
    </button>
  );
}

export default Button;
